(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const w1y = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const mx = x + w1x, my = y + w1y;
  const w2x = Math.sin(my * 0.025 + t * 0.15) * 8 + Math.cos(mx * 0.03 - t * 0.4) * 6;
  const w2y = Math.cos(mx * 0.022 - t * 0.3) * 8 + Math.sin(my * 0.028 + t * 0.2) * 6;
  const sx = mx + w2x, sy = my + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65)*40, 0.14, 1.3, 0.6],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*50, 0.05, 2.8, 1.3]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, amp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
    hS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * amp * 0.5;
  }
  const act = aS/8, inh = iS/8, harm = hS/8;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08-sy*0.06+t*1.5) + Math.cos(sx*0.07+sy*0.09-t*1.3))/2;
  const bgFine = Math.sin(sx*0.15+sy*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg = bg1*0.4 + bg2*0.2 + bgFine;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial = Math.sin(dist*0.08 - t*2) * Math.cos(ang*2 + t*0.5) * 0.3;
  const raw = act - inh*0.7 + bg*0.3 + spiral + radial + harm*0.4;
  const reaction1 = Math.tanh(raw * 2.2);
  const feedback = Math.sin(reaction1 * 3 + t) * 0.15;
  const reaction2 = Math.tanh((raw + feedback) * 2.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.2-sy*0.08+t*0.7)*0.3)*1.5)*0.3;
  const blend = reaction2*0.65 + cell*0.2 + harm*0.15, v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,58,88],[18,108,118],[45,152,118],[120,175,80],[195,185,65],[225,155,55],[215,100,65],[185,60,72],[140,40,85],[85,25,75],[35,15,60],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.8+Math.sin(reaction2*Math.PI)*0.2, edge = Math.abs(reaction2)>0.7?1.15:1.0;
  const glow = Math.max(0, 1-Math.abs(reaction2)*2)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*80)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*100)|0)
  ];
}
